<script>let poItemIndex=1;function addPoItem(){const w=document.getElementById('po-items');const row=w.firstElementChild.cloneNode(true);row.querySelectorAll('select,input').forEach(e=>{e.name=e.name.replace(/items\[\d+\]/,'items['+poItemIndex+']');if(e.tagName==='SELECT')e.selectedIndex=0;else e.value='';});w.appendChild(row);poItemIndex++;}</script>
